"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Original-frame other-before-ego entry at one median-opening crossing."""
import hashlib
import json
import math
from pathlib import Path
from shapely.geometry import MultiPoint, Polygon

REQUIRED=("junction_context.json","crossing_history.jsonl","video_frames.jsonl")

def _finite(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)

def _rows(path):return [json.loads(s) for s in path.read_text().splitlines() if s.strip()]

def _body(actor):
    values=actor.get("body_vertices_xy_m")
    if not isinstance(values,list) or len(values)<4:raise ValueError("Missing complete body")
    points=[]
    for point in values:
        if not isinstance(point,list) or len(point)!=2:raise ValueError("Invalid body vertex")
        points.append((_finite(point[0],"body x"),_finite(point[1],"body y")))
    body=MultiPoint(points).convex_hull
    if body.area<=0:raise ValueError("Degenerate body")
    return body

def analyze(root:Path, *, allow_exceptions=False)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/"junction_context.json").read_text())
    for key in ("native_map_id","intersection_id","ego_highway_id","other_highway_id",
                "ego_road_id","other_road_id","crossing_geometry_source","all_entrances_source",
                "official_device_inventory_source","median_spacing_source"):
        if ctx.get(key) is None:raise ValueError("Missing sourced crossing context: "+key)
    if ctx["ego_highway_id"]==ctx["other_highway_id"] or ctx.get("same_statutory_crossing") is not True:
        raise ValueError("Different-highway same-crossing activation not sourced")
    if ctx.get("official_device_controls_crossing") is not False:
        raise ValueError("Official-device exclusion unresolved")
    exception=ctx.get("opposite_approach_with_left_turn")
    if type(exception) is not bool:
        raise ValueError("Opposite-direction left-turn exclusion unresolved")
    if exception and not allow_exceptions:
        raise ValueError("Opposite-direction left-turn exclusion unresolved")
    crossing=Polygon(ctx.get("intersection_polygon_xy_m",[]))
    if not crossing.is_valid or crossing.area<=0:raise ValueError("Invalid crossing polygon")
    rows,frames=_rows(root/"crossing_history.jsonl"),_rows(root/"video_frames.jsonl")
    if len(rows)<3 or len(rows)!=len(frames):raise ValueError("Incomplete entry history")
    first={"ego":None,"other":None};samples=[];prev=(-1,-math.inf)
    for i,(row,frame) in enumerate(zip(rows,frames)):
        fid,time=row.get("frame"),_finite(row.get("time_s"),"time")
        if type(fid) is not int or fid<=prev[0] or time<=prev[1]:raise ValueError("Nonmonotone original history")
        prev=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original video frame join failed")
        sample={"frame":fid,"time_s":time}
        for role in ("ego","other"):
            actor=row.get(role)
            if not isinstance(actor,dict) or actor.get("intersection_id")!=ctx["intersection_id"] or actor.get("road_id")!=ctx[role+"_road_id"]:
                raise ValueError("Participant crossing identity mismatch")
            inside=_body(actor).intersects(crossing)
            if i==0 and inside:raise ValueError("Missing pre-entry history")
            if inside and first[role] is None:first[role]={"frame":fid,"time_s":time}
            sample[role+"_inside"]=inside
        if row.get("ego_vertices_m") != row["ego"]["body_vertices_xy_m"]:
            raise ValueError("Pinned physical ego body differs from measured original body")
        samples.append(sample)
    if not all(first.values()):raise ValueError("Both original body entries required")
    other_before=first["other"]["time_s"]<first["ego"]["time_s"]
    other_at_ego=next(s["other_inside"] for s in samples if s["frame"]==first["ego"]["frame"])
    return {"format":"worker-median-crossing-other-precedence","sources":hashes,"first_body_entry":first,
            "other_enters_before_ego":other_before,"other_body_inside_at_ego_entry":other_at_ego,
            "opposite_approach_with_left_turn":exception,
            "subsection_1_applicable_on_declared_exception":not exception,
            "entry_time_difference_s":first["ego"]["time_s"]-first["other"]["time_s"],
            "samples":samples,"yield_judgment":"unresolved; body entry alone does not establish yielding",
            "legal_conclusion":"unresolved"}

"""Saved-only median crossing measurement from retained Native sources."""
import argparse
import hashlib
import json
from pathlib import Path

from crossing_precedence import analyze

CAMERAS = ("overview.mkv", "approach.mkv", "reference_corner.mkv",
           "driver_reference.mkv")


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _measurement(method, value, sources, names):
    return {"method": method, "value": value,
            "sources": {name: sources[name] for name in names}}


def measure_crossing_context(report, context):
    """Expose the declared site identities without deciding statutory identity."""
    names = ("junction_context.json",)
    value = {key: context[key] for key in (
        "native_map_id", "intersection_id", "ego_highway_id", "other_highway_id",
        "ego_road_id", "other_road_id", "same_statutory_crossing",
        "crossing_geometry_source", "median_spacing_source")}
    value["legal_conclusion"] = "unresolved"
    return _measurement("measure_crossing_context", value, report["sources"], names)


def measure_body_entry(report):
    names = ("junction_context.json", "crossing_history.jsonl", "video_frames.jsonl")
    value = {key: report[key] for key in (
        "first_body_entry", "other_enters_before_ego",
        "other_body_inside_at_ego_entry", "entry_time_difference_s")}
    value["yield_judgment"] = "unresolved"
    return _measurement("measure_body_entry", value, report["sources"], names)


def measure_device_context(report, context):
    names = ("junction_context.json",)
    value = {"official_device_controls_crossing":
             context["official_device_controls_crossing"],
             "inventory_source": context["official_device_inventory_source"],
             "subsection_4_qualification": "unresolved"}
    return _measurement("measure_device_context", value, report["sources"], names)


def measure_turn_exception(report, context):
    names = ("junction_context.json",)
    value = {"opposite_approach_with_left_turn":
             context["opposite_approach_with_left_turn"],
             "exception_source_status": "declared; independent turn audit required"}
    return _measurement("measure_turn_exception", value, report["sources"], names)


def measure_yield_control(report, attempt, case_id):
    """Check original controller decisions; physical yielding remains unjudged."""
    path = Path(attempt) / "controller_history.jsonl"
    rows = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    if len(rows) != len(report["samples"]):
        raise ValueError("Incomplete original yield controller history")
    entered = False
    held_count = 0
    for row, sample in zip(rows, report["samples"]):
        if (row.get("frame") != sample["frame"] or
                row.get("time_s") != sample["time_s"] or
                row.get("selected_case_id") != case_id):
            raise ValueError("Original yield controller frame or case join failed")
        for key in ("ego_held", "other_body_inside_before_tick",
                    "other_entered_once_before_tick", "precedence_hold"):
            if type(row.get(key)) is not bool:
                raise ValueError("Missing boolean yield controller state: " + key)
        entered = entered or row["other_body_inside_before_tick"]
        if row["other_entered_once_before_tick"] is not entered:
            raise ValueError("Original other-entry controller state changed")
        required_hold = (not entered or row["other_body_inside_before_tick"])
        if case_id.endswith("__source_verified_precedence"):
            if row["precedence_hold"] is not required_hold or (required_hold and not row["ego_held"]):
                raise ValueError("Precedence controller released ego before other clearance")
        elif row["precedence_hold"]:
            raise ValueError("Nonprecedence case used precedence hold")
        held_count += row["ego_held"]
    sources = dict(report["sources"])
    sources["controller_history.jsonl"] = _sha(path)
    names = ("crossing_history.jsonl", "video_frames.jsonl", "controller_history.jsonl")
    value = {"controller_rows": len(rows), "ego_held_frames": held_count,
             "other_entry_seen_before_tick": entered,
             "policy": "other-body clearance" if case_id.endswith("__source_verified_precedence") else "scheduled release",
             "physical_yield_judgment": "unresolved"}
    return _measurement("measure_yield_control", value, sources, names)


def finalize(attempt: Path, output: Path) -> dict:
    from worker_exchange.native_output import physical_result, write_result

    attempt, output = Path(attempt), Path(output)
    if output.exists() or (attempt / "result.json").exists():
        raise ValueError("Retain previous finalization; choose a fresh attempt")
    required = ("config.json", "junction_context.json", "crossing_history.jsonl",
                "video_frames.jsonl", "controller_history.jsonl", "trace.jsonl",
                "capture/evidence.jsonl", *CAMERAS)
    for name in required:
        if not (attempt / name).is_file():
            raise ValueError("Missing required source: " + name)
    config = json.loads((attempt / "config.json").read_text())
    case_id = config.get("selected_case_id", "")
    if not case_id.startswith("testing__C125714__NRS-484B-250-1__motor_vehicle_driver__"):
        raise ValueError("Exact C125714 subsection-1 case required")
    if config.get("law_id") != "NRS-484B-250-1" or config.get("cell_id") != "C125714":
        raise ValueError("Exact law and cell required")
    expected = config.get("expected_other_enters_before_ego")
    if type(expected) is not bool:
        raise ValueError("Explicit expected entry order required")
    physical = config.get("physical_completion", {})
    if "junction_context.json" not in physical.get("context_sources", []):
        raise ValueError("Pinned physical assessor must read sourced crossing polygon")
    if physical.get("body_key") != "ego_vertices_m":
        raise ValueError("Pinned physical assessor must read original ego body")
    description = config.get("recording_description")
    if not isinstance(description, dict):
        raise ValueError("Recording description required")
    if case_id.endswith("__source_verified_opposite_intends_left"):
        from turn_exception_audit import audit_source
        original_rows = [line for line in (attempt / "crossing_history.jsonl").read_text().splitlines() if line.strip()]
        audit_source(attempt, "intends_left", len(original_rows))
    report = analyze(attempt, allow_exceptions=case_id.endswith("__source_verified_opposite_intends_left"))
    yield_measurement = measure_yield_control(report, attempt, case_id)
    sources = dict(report["sources"])
    sources["controller_history.jsonl"] = _sha(attempt / "controller_history.jsonl")
    source_context = json.loads((attempt / "junction_context.json").read_text())
    channels = attempt / "channels"
    if channels.exists():
        raise ValueError("Retain prior derived channels; choose a fresh attempt")
    channels.mkdir()
    for role in ("ego", "other"):
        with (channels / (role + "_inside.jsonl")).open("x") as stream:
            for sample in report["samples"]:
                stream.write(json.dumps({"time_s": sample["time_s"],
                                         "original_frame": sample["frame"],
                                         "value": int(sample[role + "_inside"])}) + "\n")
    with (channels / "yield_control.jsonl").open("x") as stream:
        for row in (json.loads(line) for line in
                    (attempt / "controller_history.jsonl").read_text().splitlines()
                    if line.strip()):
            stream.write(json.dumps({
                "time_s": row["time_s"], "original_frame": row["frame"],
                "value": {key: row[key] for key in (
                    "ego_held", "other_body_inside_before_tick",
                    "other_entered_once_before_tick", "precedence_hold")},
            }) + "\n")
    context = {
        "format": "worker-median-crossing-measurements",
        "first_body_entry": report["first_body_entry"],
        "other_enters_before_ego": report["other_enters_before_ego"],
        "other_body_inside_at_ego_entry": report["other_body_inside_at_ego_entry"],
        "entry_time_difference_s": report["entry_time_difference_s"],
        "source_hashes": sources,
        "legal_conclusion": "unresolved",
    }
    context["entry_context"] = {
        "first_body_entry": report["first_body_entry"],
        "other_enters_before_ego": report["other_enters_before_ego"],
        "other_body_inside_at_ego_entry": report["other_body_inside_at_ego_entry"],
        "source_hashes": sources,
    }
    (channels / "crossing_context.json").write_text(json.dumps(context, indent=2) + "\n")
    measured = report["other_enters_before_ego"]
    result = {
        "case_id": case_id,
        "measured_values": {
            "other_enters_before_ego": measured,
            "other_body_inside_at_ego_entry": report["other_body_inside_at_ego_entry"],
            "entry_time_difference_s": report["entry_time_difference_s"],
        },
        "target_checks": [{
            "target": "other_enters_before_ego", "requested": expected,
            "measured": measured, "method": "original complete-body entry at one sourced crossing",
            "tolerance": 0, "matched": measured is expected,
            "physical_cause_confirmed": False,
            "cause_evidence": ["crossing_history.jsonl", "junction_context.json",
                               "video_frames.jsonl"],
        }],
        "setup_confirmed": False, "behavior_attempted": False,
        "maneuver_completed": False,
        "termination_reason": "Saved original-source analysis; independent physical review pending",
        "physical_failure_flags": ["statutory crossing identity and yielding judgment unverified"],
        "trace_reference": "trace.jsonl", "video_references": list(CAMERAS),
        "video_frame_map_reference": "video_frames.jsonl",
        "recording_description": description,
        "recording_evidence": [
            {"name": role + "_inside", "unit": "boolean sample",
             "reference": "channels/" + role + "_inside.jsonl"}
            for role in ("ego", "other")
        ] + [{"name": "entry_context", "unit": "structured record",
              "reference": "channels/crossing_context.json"},
             {"name": "yield_control", "unit": "structured record",
              "reference": "channels/yield_control.jsonl"}],
        "source_evidence_hashes": sources,
        "capture_evidence_sha256": _sha(attempt / "capture/evidence.jsonl"),
        "realized_observables": {},
    }
    result = physical_result(attempt, result)
    write_result(attempt, result)
    analysis = {"format": "worker-median-crossing-saved-analysis",
                "case_id": case_id, "source_report": report,
                "crossing_context": context,
                "measurements": {
                    "crossing_identity": measure_crossing_context(report, source_context),
                    "body_entry_order": measure_body_entry(report),
                    "device_exclusion_context": measure_device_context(report, source_context),
                    "opposite_left_turn_context": measure_turn_exception(report, source_context),
                    "yield_control_attempt": yield_measurement,
                },
                "physical_acceptance_claimed": False}
    output.write_text(json.dumps(analysis, indent=2, allow_nan=False) + "\n")
    return analysis


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    finalize(Path(args.attempt), Path(args.output))


if __name__ == "__main__":
    main()

"""Construct and check two Native approaches to one reviewed median crossing."""
import math
from shapely.geometry import Point, Polygon


def _location(transform):
    location = transform.location
    x, y = float(location.x), float(location.y)
    if not (math.isfinite(x) and math.isfinite(y)):
        raise ValueError("Nonfinite approach location")
    return x, y


def _waypoint(world_map, transform, label):
    waypoint = world_map.get_waypoint(transform.location, project_to_road=False)
    if waypoint is None:
        raise ValueError("No Native waypoint for " + label)
    return waypoint


def _forward_alignment(approach, entry):
    ax, ay = _location(approach)
    ex, ey = _location(entry)
    dx, dy = ex - ax, ey - ay
    length = math.hypot(dx, dy)
    if length < 3:
        raise ValueError("Approach begins too near crossing entry")
    yaw = math.radians(float(approach.rotation.yaw))
    alignment = (math.cos(yaw) * dx + math.sin(yaw) * dy) / length
    if alignment < 0.8:
        raise ValueError("Approach heading does not enter crossing")
    return alignment


def plan_approaches(world_map, ego_approach, ego_entry, other_approach,
                    other_entry, crossing_polygon_xy_m, crossing_id,
                    polygon_source, entrance_source):
    """Check executable spawn/entry geometry; statutory identity still needs review."""
    if not polygon_source or not entrance_source:
        raise ValueError("Reviewed crossing polygon and entrance sources required")
    polygon = Polygon(crossing_polygon_xy_m)
    if not polygon.is_valid or polygon.area <= 0:
        raise ValueError("Invalid crossing polygon")
    approaches = {}
    for role, start, entry in (("ego", ego_approach, ego_entry),
                               ("other", other_approach, other_entry)):
        start_point, entry_point = Point(_location(start)), Point(_location(entry))
        if polygon.intersects(start_point):
            raise ValueError(role + " spawn is already in crossing")
        if not polygon.intersects(entry_point):
            raise ValueError(role + " entry misses crossing polygon")
        start_wp = _waypoint(world_map, start, role + " approach")
        entry_wp = _waypoint(world_map, entry, role + " entry")
        if start_wp.is_junction:
            raise ValueError(role + " approach begins inside Native junction")
        if not entry_wp.is_junction or entry_wp.get_junction().id != crossing_id:
            raise ValueError(role + " entry is not in selected Native junction")
        alignment = _forward_alignment(start, entry)
        approaches[role] = {
            "road_id": start_wp.road_id, "lane_id": start_wp.lane_id,
            "entry_road_id": entry_wp.road_id, "entry_lane_id": entry_wp.lane_id,
            "spawn_xy_m": list(start_point.coords[0]),
            "entry_xy_m": list(entry_point.coords[0]),
            "heading_alignment": alignment,
        }
    if approaches["ego"]["road_id"] == approaches["other"]["road_id"]:
        raise ValueError("Different Native approach roads required")
    return {
        "native_junction_id": crossing_id,
        "candidate_same_native_junction": True,
        "statutory_same_crossing_verified": False,
        "crossing_polygon_xy_m": crossing_polygon_xy_m,
        "crossing_geometry_source": polygon_source,
        "all_entrances_source": entrance_source,
        "approaches": approaches,
    }

"""Build another road participant and inventory devices at the shared crossing."""
from contextlib import contextmanager
from median_geometry import plan_approaches

def verify_uncontrolled_crossing(world, crossing_id, entrance_road_lanes):
    if len(entrance_road_lanes)<2 or len({road for road,_ in entrance_road_lanes})<2:
        raise ValueError("Different highway entrance roads required")
    devices=list(world.get_actors().filter("traffic.traffic_light*"))
    devices+=list(world.get_actors().filter("traffic.stop*"))
    devices+=list(world.get_actors().filter("traffic.yield*"))
    controlling=[]
    for actor in devices:
        if not hasattr(actor,"get_affected_lane_waypoints"):
            raise ValueError("Official device geometry requires source review")
        if any(wp.road_id==road and wp.lane_id==lane for wp in actor.get_affected_lane_waypoints() for road,lane in entrance_road_lanes):
            controlling.append(actor.id)
    if controlling:raise ValueError("Official device governs an entrance")
    return {"crossing_id":crossing_id,"entrance_road_lanes":list(entrance_road_lanes),"native_controlling_device_ids":[]}

@contextmanager
def spawn_other(world, blueprint, transform):
    actor=world.try_spawn_actor(blueprint,transform)
    if actor is None:raise ValueError("Other participant Native spawn failed")
    try:yield actor
    finally:actor.destroy()


@contextmanager
def construct_crossing_candidate(world, ego_approach, ego_entry,
                                 other_approach, other_entry, other_blueprint,
                                 crossing_polygon_xy_m, crossing_id,
                                 polygon_source, entrance_source):
    """Own the other actor after geometry and official-device checks pass."""
    plan = plan_approaches(world.get_map(), ego_approach, ego_entry,
                           other_approach, other_entry, crossing_polygon_xy_m,
                           crossing_id, polygon_source, entrance_source)
    lanes = [(plan["approaches"][role]["road_id"],
              plan["approaches"][role]["lane_id"]) for role in ("ego", "other")]
    plan["device_inventory"] = verify_uncontrolled_crossing(world, crossing_id, lanes)
    with spawn_other(world, other_blueprint, other_approach) as other:
        yield plan, other

"""CPU-checkable steering along an authored Native crossing route."""
import math
from shapely.geometry import LineString, Point, Polygon


def validate_route(points, approach, entry, label, crossing_polygon=None):
    if not isinstance(points, list) or len(points) < 3:
        raise ValueError(label + " route needs approach, entry and exit points")
    for point in points:
        if not isinstance(point, list) or len(point) != 2 or any(
                type(v) not in (int, float) or not math.isfinite(v) for v in point):
            raise ValueError(label + " route needs finite XY points")
    if math.dist(points[0], approach[:2]) > 5 or min(
            math.dist(point, entry[:2]) for point in points[1:-1]) > 5:
        raise ValueError(label + " route differs from reviewed approach or entry")
    if any(math.dist(a, b) < 1 for a, b in zip(points, points[1:])):
        raise ValueError(label + " route has duplicate or near-duplicate points")
    if math.dist(points[-1], entry[:2]) < 3:
        raise ValueError(label + " route has no exit beyond crossing entry")
    if crossing_polygon is not None:
        crossing = Polygon(crossing_polygon)
        if not crossing.is_valid or crossing.area <= 0:
            raise ValueError("Valid crossing polygon required for route")
        if crossing.intersects(Point(points[0])):
            raise ValueError(label + " route starts within crossing")
        if crossing.intersects(Point(points[-1])):
            raise ValueError(label + " route ends within crossing")
        if not LineString(points).intersects(crossing) or not any(
                crossing.contains(Point(point)) for point in points[1:-1]):
            raise ValueError(label + " route does not traverse crossing interior")
    return points


def steering_command(x, y, yaw_deg, points, progress=1, lookahead_m=5.0):
    """Return Native steer (+right) and monotone target index for a route."""
    if any(not math.isfinite(v) for v in (x, y, yaw_deg, lookahead_m)) or lookahead_m <= 0:
        raise ValueError("Finite route controller pose and lookahead required")
    if type(progress) is not int or not 1 <= progress < len(points):
        raise ValueError("Valid route target index required")
    while progress < len(points) - 1 and math.dist((x, y), points[progress]) < lookahead_m:
        progress += 1
    target = points[progress]
    distance = math.dist((x, y), target)
    if distance < 0.01:
        return 0.0, progress
    yaw = math.radians(yaw_deg)
    heading = math.atan2(target[1] - y, target[0] - x)
    error = (heading - yaw + math.pi) % (2 * math.pi) - math.pi
    curvature = 2 * math.sin(error) / max(distance, lookahead_m)
    # CARLA VehicleControl.steer is positive for a right turn.
    steer = -math.atan(2.8 * curvature) / math.radians(35)
    return max(-1.0, min(1.0, steer)), progress

